/**
 * The catalog: sessions that exist on disk in the shared omp session directory, open in the app
 * or not. Distinct from a session's view model (`session.ts`), which only exists for sessions the
 * sidecar has open.
 */
import { isRecord } from "./guards";

/** One stored session, as omp's own listing (the one behind `omp --resume`) reports it. */
export interface StoredSession {
  readonly id: string;
  /** Absolute folder the session was started in. Never empty: sessions without one are not listed. */
  readonly cwd: string;
  /** omp's own title (typed by the user, or generated by omp); null when the file has none. */
  readonly title: string | null;
  /** First prompt, cut to {@link FIRST_PROMPT_MAX} characters; null if the session has none yet. */
  readonly firstPrompt: string | null;
  /** Last write to the session file, in epoch milliseconds. */
  readonly modified: number;
  /** Assistant replies persisted so far. */
  readonly turns: number;
}

/** Longest first prompt the sidecar sends; the sidebar shows far less. */
export const FIRST_PROMPT_MAX = 200;

/** Newest first, as the CLI picker orders them. */
export interface SessionListResult {
  readonly sessions: readonly StoredSession[];
}

function isStoredSession(v: unknown): v is StoredSession {
  return (
    isRecord(v) &&
    typeof v.id === "string" &&
    typeof v.cwd === "string" &&
    (v.title === null || typeof v.title === "string") &&
    (v.firstPrompt === null || typeof v.firstPrompt === "string") &&
    typeof v.modified === "number" &&
    typeof v.turns === "number"
  );
}

export function isSessionListResult(v: unknown): v is SessionListResult {
  return isRecord(v) && Array.isArray(v.sessions) && v.sessions.every(isStoredSession);
}
